#define main legacy_main
#include "stencil3d-cuda/main.cu"
#undef main
#include <vector>
#include <cmath>
const int S=30,V=S*S*S;double mat[3][3]={{2,.125,.25},{.125,3,.375},{.25,.375,4}};
std::vector<double> oracle(const std::vector<double>&p,const std::vector<double>&s){auto at=[&](int x,int y,int z){return p[z+S*(y+S*x)];};auto face=[&](int axis,int x,int y,int z){double xd,yd,zd;if(axis==0){xd=at(x,y,z)-at(x-1,y,z);yd=(-at(x-1,y-1,z)+at(x-1,y+1,z)-at(x,y-1,z)+at(x,y+1,z))/4;zd=(-at(x-1,y,z-1)+at(x-1,y,z+1)-at(x,y,z-1)+at(x,y,z+1))/4;}else if(axis==1){xd=(-at(x-1,y-1,z)-at(x-1,y,z)+at(x+1,y-1,z)+at(x+1,y,z))/4;yd=at(x,y,z)-at(x,y-1,z);zd=(-at(x,y-1,z-1)+at(x,y-1,z+1)-at(x,y,z-1)+at(x,y,z+1))/4;}else{xd=(-at(x-1,y,z-1)-at(x-1,y,z)+at(x+1,y,z-1)+at(x+1,y,z))/4;yd=(-at(x,y-1,z-1)-at(x,y-1,z)+at(x,y+1,z-1)+at(x,y+1,z))/4;zd=at(x,y,z)-at(x,y,z-1);}int i=z+S*(y+S*x);return s[axis*3*V+i]*xd+s[(axis*3+1)*V+i]*yd+s[(axis*3+2)*V+i]*zd;};std::vector<double>o(V,0);for(int x=1;x<S-1;x++)for(int y=1;y<S-1;y++)for(int z=1;z<S-1;z++)o[z+S*(y+S*x)]=face(0,x+1,y,z)-face(0,x,y,z)+face(1,x,y+1,z)-face(1,x,y,z)+face(2,x,y,z+1)-face(2,x,y,z);return o;}
int main(){std::vector<double>p(V),constant(V,1.25),sigma(9*V),out(V);for(int i=0;i<V;i++)p[i]=double(i%19-9)/8;for(int axis=0;axis<3;axis++)for(int dir=0;dir<3;dir++)for(int i=0;i<V;i++)sigma[(axis*3+dir)*V+i]=mat[axis][dir]*(1.+double(i%7)/16);auto want=oracle(p,sigma),zero=oracle(constant,sigma);double*P,*Q,*O,*C;cudaMalloc(&P,V*8);cudaMalloc(&C,V*8);cudaMalloc(&Q,9*V*8);cudaMalloc(&O,V*8);cudaMemcpy(P,p.data(),V*8,cudaMemcpyHostToDevice);cudaMemcpy(C,constant.data(),V*8,cudaMemcpyHostToDevice);cudaMemcpy(Q,sigma.data(),9*V*8,cudaMemcpyHostToDevice);auto run=[&](double*input){stencil3d<<<dim3(2,2,2),dim3(16,16)>>>(input,O,Q,Q+3*V,Q+6*V,S,S,S);};run(P);run(C);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){double total=0,err=0;bool ok=true;std::vector<double>got;for(int mode=0;mode<2;mode++){cudaMemset(O,0,V*8);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<10;rep++)run(mode==0?P:C);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;cudaMemcpy(out.data(),O,V*8,cudaMemcpyDeviceToHost);auto&reference=mode==0?want:zero;for(int i=0;i<V;i++){err=std::max(err,fabs(out[i]-reference[i]));ok=ok&&std::isfinite(out[i])&&fabs(out[i]-reference[i])<=1e-10;}got.insert(got.end(),out.begin(),out.end());}char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(got.data(),8,got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":54000,\"max_abs_error\":%.15g,\"timing_region\":\"sum_nonuniform_and_constant_anisotropic_stencil_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":54000,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",err,path);if(!ok)return 1;}cudaFree(P);cudaFree(C);cudaFree(Q);cudaFree(O);}
